import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第十八卦 蠱 山風蠱 艮上巽下","description":"周易 - 第十八卦 蠱 山風蠱 艮上巽下","frontmatter":{"title":"第十八卦 蠱 山風蠱 艮上巽下","description":"周易 - 第十八卦 蠱 山風蠱 艮上巽下"},"headers":[],"relativePath":"classics/zhouyi/019.md","filePath":"classics/zhouyi/019.md"}'),l={name:"classics/zhouyi/019.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="蠱" tabindex="-1">蠱 <a class="header-anchor" href="#蠱" aria-label="Permalink to “蠱”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>元亨，利涉大川。先甲三日，後甲三日。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>蠱，剛上而柔下，巽而止，蠱。蠱，元亨，而天下治也。利涉大川，往有事也。先甲三日，後甲三日，終則有始，天行也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>山下有風，蠱；君子以振民育德。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>幹父之蠱，有子，考無咎，厲終吉。象 曰：幹父之蠱，意承考也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>幹母之蠱，不可貞。象曰：幹母之蠱，得中道也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>幹父小有晦，無大咎。象曰：幹父之蠱，終無咎也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>裕父之蠱，往見吝。象曰：裕父之蠱，往未得也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>幹父之蠱，用譽。象曰：幹父之蠱；承以德也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>不事王侯，高尚其事。象曰：不事王侯，志可則也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
